object Solution { def reverseWords(s: Array[Char]): Unit = { reverse(s, 0, s.length - 1); var start = 0; for (end <- 0 to s.length) if (end == s.length || s(end) == ' ') { reverse(s, start, end - 1); start = end + 1 } } private def reverse(s: Array[Char], left: Int, right: Int): Unit = { var l = left; var r = right; while (l < r) { val t = s(l); s(l) = s(r); s(r) = t; l += 1; r -= 1 } } }
